        ttk.Checkbutton(ctrl, text='Enable Dynamic Zoom', variable=self.recon_dynamic_zoom_var, command=self._toggle_recon_dynamic_zoom).pack(side='left', padx=(12, 4))
        self.field_index_var = tk.IntVar(value=0)
